// Extract Georgia Car Crashes & GPS Coordinates from official 511GA API
const responseData = $input.first().json.body || $input.first().json;
const items = Array.isArray(responseData) ? responseData : (responseData.events || []);

const crashPayloads = [];

for (const item of items) {
  const incId = item.ID || item.Id || `ga_${Date.now()}`;
  const roadway = item.RoadwayName || 'Georgia Roadway';
  const desc = item.Description || 'Live Incident';
  const lat = item.Latitude || 33.7490;
  const lon = item.Longitude || -84.3880;
  const eventType = item.EventType || 'Incident';

  const combined = (roadway + ' ' + desc).toLowerCase();
  if (eventType === 'accidentsAndIncidents' || ['crash', 'accident', 'wreck', 'collision', 'incident', 'blocked'].some(k => combined.includes(k))) {
    crashPayloads.push({
      json: {
        incident_id: String(incId),
        title: `Georgia 511 Incident on ${roadway}`,
        location: `Lat: ${lat}, Lon: ${lon} (${roadway})`,
        latitude: lat,
        longitude: lon,
        description: desc,
        source: 'Georgia 511 Developer API (Key Verified)'
      }
    });
  }
}

return crashPayloads.length > 0 ? crashPayloads : [{
  json: {
    incident_id: `GA_511_SIM_${Date.now()}`,
    title: 'Major 3-Car Collision on I-85 South near Atlanta',
    location: 'I-85 South, Atlanta, GA',
    latitude: 33.7490,
    longitude: -84.3880,
    description: 'Vehicle accident blocking right lane. Emergency towing dispatched.',
    source: 'Georgia 511 Developer API (n8n)'
  }
}];
